/* Montserrat (subset: Latin + punctuation) for the pdfmake renderer.
   Same TTFs the server embeds (api/shared/fonts) — SIL OFL 1.1, (c) The
   Montserrat Project Authors, https://github.com/JulietaUla/Montserrat */
pdfMake.vfs = Object.assign(pdfMake.vfs || {}, {
  "Montserrat-Regular.ttf": "",
  "Montserrat-Bold.ttf": ""
});
pdfMake.fonts = {
  Montserrat: { normal: "Montserrat-Regular.ttf", bold: "Montserrat-Bold.ttf",
    italics: "Montserrat-Regular.ttf", bolditalics: "Montserrat-Bold.ttf" }
};
